  it("serializes skills across processes and recovers a dead lock owner", async () => {
    const dir = mkdtempSync(join(tmpdir(), "autogen-lock-"));
    const lock = join(dir, ".history", "locks", "locked-skill.lock");
    const childScript = `
      const fs = require("node:fs");
      const path = ${JSON.stringify(lock)};
      fs.mkdirSync(path, { recursive: true, mode: 0o700 });
      fs.writeFileSync(path + "/owner.json", JSON.stringify({
        pid: process.pid,
        token: "child-owner",
        createdAt: new Date().toISOString()
      }) + "\\n");
      process.stdout.write("held\\n");
      setInterval(() => {}, 1000);
    `;
    const child = spawn(process.execPath, ["-e", childScript], { stdio: ["ignore", "pipe", "inherit"] });
    await new Promise<void>((resolvePromise, reject) => {
      child.once("error", reject);
      child.stdout.once("data", () => resolvePromise());
    });
    const m = new AutoSkillManager({ dir, mode: "auto", lockTimeoutMs: 40 });
    try {
      expect(() => m.execute({
        action: "create",
        name: "locked-skill",
        description: "Locked",
        instructions,
      })).toThrow(/timed out waiting for skill mutation lock/);
      expect(m.execute({
        action: "create",
        name: "other-skill",
        description: "Other",
        instructions,
      }).revision).toMatch(/^[a-f0-9]{64}$/);
    } finally {
      child.kill("SIGKILL");
      await new Promise(resolvePromise => child.once("exit", resolvePromise));
    }
    expect(m.execute({
      action: "create",
      name: "locked-skill",
      description: "Recovered",
      instructions,
    }).revision).toMatch(/^[a-f0-9]{64}$/);
    expect(existsSync(lock)).toBe(false);
  });

