/home/swarm/Work/Pi-Swarm/.pi/agent-sessions/session:agent-23d1b0eae344b8905d3a.jsonl:291:{"type":"message","id":"449a5247","parentId":"68ded9fc","timestamp":"2026-09-05T05:03:59.391Z","message":{"role":"toolResult","toolCallId":"call_J9shXXSSqpVx7e1TAz4RPE6b","toolName":"codemode","content":[{"type":"text","text":"{\n  \"ok\": true,\n  \"value\": [\n    \"import { registerAutoSkills, type Config } from \\\"../../autogenskills/src/index.ts\\\";\\nimport { fileURLToPath } from \\\"node:url\\\";\\nimport { join, resolve } from \\\"node:path\\\";\\nimport { readFileSync, writeFileSync, mkdirSync } from \\\"node:fs\\\";\\nimport \\\"../hook-state.ts\\\";\\n\\n/** Pi adapter for Swarm's stateful autogenerated-skills lifecycle. */\\nexport interface AutoSkillsExtensionOptions extends Config {}\\n\\nconst settingsFile = (cwd: string) => join(resolve(cwd), \\\".pi\\\", \\\"swarm-settings.json\\\");\\nfunction autogenMode(cwd: string): Config[\\\"mode\\\"] {\\n  const env = process.env.SWARM_AUTOGEN_MODE as Config[\\\"mode\\\"] | undefined;\\n  if (env && [\\\"never\\\", \\\"manual\\\", \\\"auto\\\"].includes(env)) return env;\\n  try {\\n    const value = JSON.parse(readFileSync(settingsFile(cwd), \\\"utf8\\\")).autogen;\\n    if (value === false || value === \\\"off\\\" || value === \\\"never\\\") return \\\"never\\\";\\n    if (value === \\\"manual\\\") return \\\"manual\\\";\\n    if (value === true || value === \\\"on\\\" || value === \\\"auto\\\") return \\\"auto\\\";\\n  } catch { /* absent settings use the Swarm default */ }\\n  return \\\"auto\\\";\\n}\\nfunction saveAutogenMode(cwd: string, mode: Config[\\\"mode\\\"]): void {\\n  const path = settingsFile(cwd); mkdirSync(join(resolve(cwd), \\\".pi\\\"), { recursive: true });\\n  let settings: any = {}; try { settings = JSON.parse(readFileSync(path, \\\"utf8\\\")); } catch {}\\n  settings.autogen = mode === \\\"never\\\" ? false : mode;\\n  writeFileSync(path, `${JSON.stringify(settings, null, 2)}\\\\n`, \\\"utf8\\\");\\n}\\n\\nexport function registerAutoSkillsExtension(pi: any, options: AutoSkillsExtensionOptions = {}) {\\n  const child = process.env.SWARM_CURATOR_CHILD === \\\"1\\\";\\n  const extensionPath = fileURLToPath(import.meta.url);\\n  const configuredDir = options.dir ?? process.env.SWARM_AUTOGEN_DIR;\\n  const dir = configuredDir?.trim() || join(process.env.HOME ?? process.cwd(), \\\".swarm\\\", \\\"skills\\\", \\\"autogen\\\");\\n  const curatorRunner = options.curatorRunner ?? (!child && typeof pi.exec === \\\"function\\\"\\n    ? async (request: Parameters<NonNullable<Config[\\\"curatorRunner\\\"]>>[0]) => {\\n      const result = await pi.exec(\\\"env\\\", [\\n        `SWARM_AUTOGEN_MODE=manual`,\\n        `SWARM_AUTOGEN_DIR=${dir}`,\\n        `SWARM_AUTOGEN_PREVIEW=${request.preview ? \\\"1\\\" : \\\"0\\\"}`,\\n        \\\"SWARM_AUTOGEN_REQUIRE_VIEW=1\\\",\\n        \\\"SWARM_AUTOGEN_ACCOUNTING_EXEMPT=1\\\",\\n        \\\"SWARM_CURATOR_CHILD=1\\\",\\n        \\\"pi\\\",\\n        \\\"--no-session\\\",\\n        \\\"--no-extensions\\\",\\n        \\\"--extension\\\", extensionPath,\\n        \\\"--no-skills\\\",\\n        \\\"--no-context-files\\\",\\n        \\\"--no-prompt-templates\\\",\\n        \\\"--tools\\\", \\\"SkillManage\\\",\\n        \\\"--mode\\\", \\\"text\\\",\\n        \\\"-p\\\", request.prompt,\\n      ], { cwd: process.cwd(), timeout: request.timeoutMs });\\n      if (result.code !== 0 || result.killed) {\\n        throw new Error(`curator child failed (${result.killed ? \\\"timeout\\\" : `exit ${result.code}`}): ${result.stderr.trim()}`);\\n      }\\n      return { output: result.stdout.trim() };\\n    }\\n    : undefined);\\n  return registerAutoSkills(pi, {\\n    ...options,\\n    budgetWidget: undefined,\\n    dir,\\n    previewOnly: options.previewOnly ?? process.env.SWARM_AUTOGEN_PREVIEW === \\\"1\\\",\\n    requireReadBeforeWrite: options.requireReadBeforeWrite ?? process.env.SWARM_AUTOGEN_REQUIRE_VIEW === \\\"1\\\",\\n    accountingExempt: options.accountingExempt ?? process.env.SWARM_AUTOGEN_ACCOUNTING_EXEMPT === \\\"1\\\",\\n    curatorRunner,\\n  });\\n}\\n\\nexport default function autogenskillsExtension(pi: any) {\\n  // Swarm autogen is enabled by default, but remains isolated from Pi's\\n  // native skill ecosystem. Persisted project settings or the environment can\\n  // disable it without exposing generated skills to Pi discovery.\\n  const cwd = resolve(pi.getCwd?.() ?? process.cwd());\\n  const mode = autogenMode(cwd);\\n  pi.registerCommand?.(\\\"swarm-autogen\\\", { description: \\\"Show or change Swarm autogenerated-skills mode (on, off, manual, status)\\\", handler: async (args: string, ctx: any) => {\\n    const value = args.trim().toLowerCase();\\n    if (value === \\\"status\\\" || !value) { ctx.ui?.notify?.(`Swarm autogen: ${mode} (default: auto; applies on next session)`, \\\"info\\\"); return; }\\n    const next = value === \\\"on\\\" ? \\\"auto\\\" : value === \\\"off\\\" ? \\\"never\\\" : value;\\n    if (![\\\"auto\\\", \\\"manual\\\", \\\"never\\\"].includes(next)) { ctx.ui?.notify?.(\\\"Usage: /swarm-autogen on|off|manual|status\\\", \\\"warning\\\"); return; }\\n    saveAutogenMode(cwd, next as Config[\\\"mode\\\"]);\\n    ctx.ui?.notify?.(`Swarm autogen set to ${next}; restart or reload the session to apply.`, \\\"info\\\");\\n  }});\\n  if (mode === \\\"never\\\") return;\\n  registerAutoSkillsExtension(pi, { mode, dir: process.env.SWARM_AUTOGEN_DIR || undefined });\\n  // Prompt composition is owned by swarm-prompt.ts. Autogen contributes\\n  // lifecycle nudges only when enabled by settings or environment.\\n}\\n\",\n    \"import { getSwarmSkillRegistry, type SkillLoaderOptions } from \\\"../lib/swarm-skill-registry.ts\\\";\\n\\nexport interface SwarmSkillsOptions extends SkillLoaderOptions { watch?: boolean; }\\n\\nexport function registerSwarmSkills(pi: any, options: SwarmSkillsOptions = {}) {\\n  // Normal operation includes installed, project, user, and autogenerated skills.\\n  // Closed mode remains explicit and only admits the configured CLI paths.\\n  const registry = getSwarmSkillRegistry(pi, { cwd: options.cwd ?? process.cwd(), ...options, closed: options.closed ?? (process.env.SWARM_SKILLS_CLOSED === \\\"1\\\") });\\n  let current = registry.refresh();\\n  const bridged: any[] = [];\\n  const originalRegister = pi.registerTool?.bind(pi);\\n  pi.registerTool = (tool: unknown) => { bridged.push(tool); originalRegister?.(tool); };\\n  (pi as any).codemodeTools = [...((pi as any).codemodeTools ?? []), ...bridged];\\n  const refresh = () => { current = registry.refresh(); };\\n  if (options.watch) registry.loader.watch(refresh);\\n  pi.on?.(\\\"session_start\\\", refresh);\\n  // Prompt composition is owned by swarm-prompt.ts. This extension owns only\\n  // discovery, invocation, and the inspection command; registering another\\n  // systemPrompt writer here can overwrite the Forge assembly.\\n  pi.registerCommand?.(\\\"skill\\\", { description: \\\"List discovered Swarm skills and their sources\\\", handler: async (_args: string, ctx: any) => {\\n    current = registry.refresh();\\n    const text = current.skills.map(s => `${s.name} [${s.source}] — ${s.description}`).join(\\\"\\\\n\\\") || \\\"No skills discovered\\\";\\n    ctx.ui?.notify?.(text, \\\"info\\\");\\n  }});\\n  pi.registerCommand?.(\\\"swarm-skills\\\", { description: \\\"List discovered Swarm skills\\\", handler: async (args: string, ctx: any) => {\\n    current = registry.refresh();\\n    const requested = args.trim();\\n    const skill = requested ? registry.find(requested) : undefined;\\n    ctx.ui?.notify?.(skill ? `${skill.name} [${skill.source}]\\\\n${skill.description}` : current.skills.map(s => `${s.name} [${s.source}] — ${s.description}`).join(\\\"\\\\n\\\") || \\\"No skills discovered\\\", \\\"info\\\");\\n  }});\\n  // The autogenskills extension owns the canonical model-facing `Skill` tool\\n  // and invokes its stateful manager. This extension must not register a second\\n  // tool with the same name; it only supplies the shared discovery registry and\\n  // the user-facing discovery commands.\\n  return { loader: registry.loader, registry, getResult: () => current };\\n}\\n\\nexport default function swarmSkillsExtension(pi: any) { return registerSwarmSkills(pi); }\\n\",\n    \"import { SkillLoader, generateAvailableSkillsXML, type LoadedSkill, type SkillLoaderOptions, type SkillLoadResult } from \\\"../../skills/src/index.ts\\\";\\n\\n/** One registry shared by the model-facing Skill tool, prompt catalog, and /skill command. */\\nexport class SwarmSkillRegistry {\\n  readonly loader: SkillLoader;\\n  private result: SkillLoadResult;\\n  constructor(options: SkillLoaderOptions = {}) { this.loader = new SkillLoader({ ...options, closed: options.closed ?? false }); this.result = this.loader.load(); }\\n  refresh(): SkillLoadResult { this.result = this.loader.load(); return this.result; }\\n  list(): LoadedSkill[] { return this.result.skills; }\\n  find(name: string): LoadedSkill | undefined { return this.result.skills.find(s => s.name === name); }\\n  catalog(): string { return generateAvailableSkillsXML(this.result.skills.filter(s => !s.disableModelInvocation)); }\\n}\\n\\nexport type { LoadedSkill, SkillLoaderOptions, SkillLoadResult };\\n\\nconst registries = new WeakMap<object, SwarmSkillRegistry>();\\nexport function getSwarmSkillRegistry(pi: object, options: SkillLoaderOptions = {}): SwarmSkillRegistry {\\n  let registry = registries.get(pi);\\n  if (!registry) { registry = new SwarmSkillRegistry(options); registries.set(pi, registry); }\\n  return registry;\\n}\\n\",\n    \"import { createHash } from \\\"node:crypto\\\";\\nimport { existsSync, readFileSync, readdirSync, statSync } from \\\"node:fs\\\";\\nimport { extname, isAbsolute, join, relative, resolve } from \\\"node:path\\\";\\nimport { registerHook } from \\\"../hook-state.ts\\\";\\nimport { getSwarmSkillRegistry } from \\\"../lib/swarm-skill-registry.ts\\\";\\n\\nimport {\\n  UPSTREAM_SOURCE,\\n  forgeSwarmSystemPrompt,\\n  swarmForgeSystemPrompt,\\n} from \\\"../../swarm-prompt/src/index.ts\\\";\\nimport { resolveActiveSystemPrompt } from \\\"./system-prompts.ts\\\";\\n\\nexport { UPSTREAM_SOURCE, forgeSwarmSystemPrompt, swarmForgeSystemPrompt };\\n\\nconst forgeMarker = \\\"<!-- pi-swarm:forge-prompt:v1 -->\\\";\\n\\nexport interface PromptExtensionEvent {\\n  systemPrompt: string;\\n  systemPromptOptions?: { cwd?: string };\\n  /** Optional Forge prompt controls supplied by the host/bridge. */\\n  swarmPrompt?: PromptAssemblyOptions;\\n}\\nexport interface PromptExtensionContext { cwd?: string; }\\nexport interface PromptProvenance { section: string; origin: string; ref: string; hash: string; bytes: number; }\\nexport interface WorkspaceContext { cwd: string; os: string; shell: string; home: string; extensions: string[]; }\\nexport interface ContextFile { path: string; content: string; }\\nexport interface PromptAssemblyOptions {\\n  cwd?: string;\\n  userPrompt?: string;\\n  tools?: Array<string | { name: string; guidance: string }>;\\n  toolGuidance?: Record<string, string>;\\n  skills?: Array<{ name: string; instructions: string; version?: string }>;\\n  contextFiles?: string[];\\n  contextFileNames?: string[];\\n  restrictions?: string[];\\n  /** Explicitly opt out of convention-file discovery. */\\n  discoverContextFiles?: boolean;\\n  maxContextFileBytes?: number;\\n}\\nexport interface PromptAssembly {\\n  prompt: string;\\n  hash: string;\\n  workspace: WorkspaceContext;\\n  provenance: PromptProvenance[];\\n  contextFiles: string[];\\n}\\n\\nconst hash = (value: string) => `sha256:${createHash(\\\"sha256\\\").update(value).digest(\\\"hex\\\")}`;\\nconst clean = (value: string) => value.replace(/\\\\r\\\\n/g, \\\"\\\\n\\\").trim();\\nconst contained = (root: string, candidate: string) => {\\n  const r = relative(root, candidate);\\n  return r === \\\"\\\" || (r !== \\\"..\\\" && !r.startsWith(`..${\\\"/\\\"}`) && !isAbsolute(r));\\n};\\nconst safeRef = (root: string, path: string) => {\\n  const absolute = resolve(root, path);\\n  return contained(root, absolute) ? absolute : undefined;\\n};\\n\\nexport function resolveWorkspace(cwd = process.cwd()): WorkspaceContext {\\n  const root = resolve(cwd);\\n  const extensions = new Set<string>();\\n  const walk = (dir: string, depth: number) => {\\n    if (depth > 2 || !existsSync(dir)) return;\\n    for (const entry of readdirSync(dir)) {\\n      const path = join(dir, entry);\\n      if (entry.startsWith(\\\".\\\") && entry !== \\\".env\\\") continue;\\n      try { statSync(path).isDirectory() ? walk(path, depth + 1) : extensions.add(extname(entry).slice(1)); } catch { /* race or unreadable */ }\\n    }\\n  };\\n  walk(root, 0);\\n  return { cwd: root, os: process.platform, shell: process.env.SHELL || \\\"unknown\\\", home: process.env.HOME || \\\"unknown\\\", extensions: [...extensions].filter(Boolean).sort() };\\n}\\n\\nfunction workspaceBlock(workspace: WorkspaceContext): string {\\n  // Keep the human-readable legacy line while retaining the structured Forge\\n  // fields used by newer consumers.\\n  return [`Current working directory: ${workspace.cwd}`, \\\"<system_information>\\\", `<operating_system>${workspace.os}</operating_system>`, `<current_working_directory>${workspace.cwd}</current_working_directory>`, `<default_shell>${workspace.shell}</default_shell>`, `<home_directory>${workspace.home}</home_directory>`, `<workspace_extensions>${workspace.extensions.join(\\\", \\\")}</workspace_extensions>`, \\\"</system_information>\\\"].join(\\\"\\\\n\\\");\\n}\\nfunction conventionalFiles(root: string, names: string[], max: number): ContextFile[] {\\n  return names.flatMap((name) => { const path = safeRef(root, name); if (!path || !existsSync(path)) return []; try { const content = readFileSync(path, \\\"utf8\\\"); return [{ path: name, content: content.slice(0, max) }]; } catch { return []; } });\\n}\\n\\nexport function assembleForgePrompt(_base: string, options: PromptAssemblyOptions = {}): PromptAssembly {\\n  const workspace = resolveWorkspace(options.cwd);\\n  const root = workspace.cwd;\\n  const max = options.maxContextFileBytes ?? 128 * 1024;\\n  const provenance: PromptProvenance[] = [];\\n  const sections: string[] = [];\\n  const add = (section: string, content: string, origin: string, ref = \\\"\\\") => { const value = clean(content); if (!value) return; sections.push(value); provenance.push({ section, origin, ref, hash: hash(value), bytes: Buffer.byteLength(value) }); };\\n  add(\\\"workspace\\\", workspaceBlock(workspace), \\\"runtime\\\", \\\"workspace\\\");\\n  add(\\\"forge\\\", `${forgeMarker}\\\\n${swarmForgeSystemPrompt}`, \\\"forge\\\", `${UPSTREAM_SOURCE}#swarmForgeSystemPrompt`);\\n  add(\\\"user\\\", options.userPrompt || \\\"\\\", \\\"configuration\\\", \\\"userPrompt\\\");\\n\\n  const tools = (options.tools || []).map((tool) => typeof tool === \\\"string\\\" ? { name: tool, guidance: options.toolGuidance?.[tool] || \\\"\\\" } : tool).filter((tool) => tool.guidance);\\n  add(\\\"tools\\\", tools.map((tool) => `### ${tool.name}\\\\n${tool.guidance}`).join(\\\"\\\\n\\\\n\\\"), \\\"configuration\\\", \\\"tools\\\");\\n  add(\\\"skills\\\", (options.skills || []).map((skill) => `### ${skill.name}${skill.version ? ` (v${skill.version})` : \\\"\\\"}\\\\n${skill.instructions}`).join(\\\"\\\\n\\\\n\\\"), \\\"skill\\\", \\\"skills\\\");\\n\\n  const names = options.contextFileNames || [\\\"AGENTS.md\\\", \\\"SWARM.md\\\"];\\n  const files = [...(options.contextFiles || []).flatMap((name) => conventionalFiles(root, [name], max)), ...(options.discoverContextFiles === false ? [] : conventionalFiles(root, names, max))];\\n  const unique = [...new Map(files.map((file) => [file.path, file])).values()].sort((a, b) => a.path.localeCompare(b.path));\\n  add(\\\"context\\\", unique.map((file) => `<context_file path=\\\"${file.path}\\\">\\\\n${file.content}\\\\n</context_file>`).join(\\\"\\\\n\\\\n\\\"), \\\"context-file\\\", unique.map((file) => file.path).join(\\\",\\\"));\\n  add(\\\"restrictions\\\", (options.restrictions || []).map((r) => `- ${r}`).join(\\\"\\\\n\\\"), \\\"policy\\\", \\\"restrictions\\\");\\n  const prompt = sections.join(\\\"\\\\n\\\\n\\\");\\n  return { prompt, hash: hash(prompt), workspace, provenance, contextFiles: unique.map((file) => file.path) };\\n}\\n\\nexport function comparePromptGolden(actual: PromptAssembly | string, golden: string): { equal: boolean; actualHash: string; goldenHash: string } {\\n  const actualText = typeof actual === \\\"string\\\" ? actual : actual.prompt;\\n  return { equal: actualText === golden, actualHash: hash(actualText), goldenHash: hash(golden) };\\n}\\n\\nexport interface PromptExtensionAPI { on(event: \\\"before_agent_start\\\", handler: (event: PromptExtensionEvent, ctx: PromptExtensionContext) => unknown): void; }\\nconst promptRegistrations = new WeakSet<object>();\\nexport function registerSwarmPrompt(pi: PromptExtensionAPI): void {\\n  if (promptRegistrations.has(pi as object)) return;\\n  promptRegistrations.add(pi as object);\\n  registerHook(pi, \\\"swarm-prompt\\\", \\\"before_agent_start\\\", (event: PromptExtensionEvent, ctx: PromptExtensionContext) => {\\n    const cwd = ctx.cwd ?? event.systemPromptOptions?.cwd ?? process.cwd();\\n    const selected = resolveActiveSystemPrompt(cwd);\\n    if (selected.kind === \\\"pi\\\") return;\\n    if (selected.kind === \\\"custom\\\") return { systemPrompt: selected.content };\\n    if (event.systemPrompt.includes(forgeMarker)) return;\\n    const assembly = assembleForgePrompt(event.systemPrompt, { cwd, ...event.swarmPrompt });\\n    const catalog = getSwarmSkillRegistry(pi as any, { cwd }).catalog();\\n    const skillGuidance = catalog ? `\\\\n\\\\n${catalog}\\\\nWhen a user request matches an available skill, invoke the Skill tool before responding; do not reproduce the skill instructions instead of invoking it.` : \\\"\\\";\\n    // Pi's native skill loader owns the Pi ecosystem. Do not inject Swarm's\\n    // install/autogen skills into the system prompt; Swarm skills remain an\\n    // explicit, user-invoked capability only.\\n    return { systemPrompt: assembly.prompt + skillGuidance };\\n  });\\n}\\nexport default function swarmPromptExtension(pi: PromptExtensionAPI): void { registerSwarmPrompt(pi); }\\n\",\n    \"import { createHash } from \\\"node:crypto\\\";\\n\\nconst webSchema = { type: \\\"object\\\", required: [\\\"query\\\"], additionalProperties: false, properties: { query: { type: \\\"string\\\" }, allowed_domains: { type: \\\"array\\\", items: { type: \\\"string\\\" }, maxItems: 5 }, excluded_domains: { type: \\\"array\\\", items: { type: \\\"string\\\" }, maxItems: 5 } } } as const;\\nconst xSchema = { type: \\\"object\\\", required: [\\\"query\\\"], additionalProperties: false, properties: { query: { type: \\\"string\\\" }, allowed_x_handles: { type: \\\"array\\\", items: { type: \\\"string\\\" }, maxItems: 10 }, excluded_x_handles: { type: \\\"array\\\", items: { type: \\\"string\\\" }, maxItems: 10 }, from_date: { type: \\\"string\\\" }, to_date: { type: \\\"string\\\" } } } as const;\\nimport { readFileSync } from \\\"node:fs\\\";\\nimport { join } from \\\"node:path\\\";\\nconst key = (name: \\\"XAI_API_KEY\\\") => {\\n  const env = process.env[name]?.trim(); if (env) return env;\\n  try { const d = JSON.parse(readFileSync(process.env.PI_SWARM_API_KEYS ?? join(process.env.HOME ?? process.cwd(), \\\".swarmos\\\", \\\"xai_oauth.json\\\"), \\\"utf8\\\")); return d?.token?.access_token?.trim(); } catch { return undefined; }\\n};\\nasync function search(tool: \\\"web_search\\\" | \\\"x_search\\\", p: any, signal?: AbortSignal) {\\n  const apiKey = key(\\\"XAI_API_KEY\\\"); if (!apiKey) throw new Error(\\\"XAI_API_KEY is not configured\\\");\\n  const body: any = { model: process.env.XAI_SEARCH_MODEL ?? \\\"grok-4.3\\\", input: [{ role: \\\"user\\\", content: p.query.trim() }], tools: [{ type: tool }], store: false };\\n  if (tool === \\\"x_search\\\") { for (const n of [\\\"allowed_x_handles\\\", \\\"excluded_x_handles\\\", \\\"from_date\\\", \\\"to_date\\\"]) if (p[n] !== undefined) body.tools[0][n] = p[n]; } else if (p.allowed_domains?.length) body.tools[0].filters = { allowed_domains: p.allowed_domains }; else if (p.excluded_domains?.length) body.tools[0].filters = { excluded_domains: p.excluded_domains };\\n  const r = await fetch(`${process.env.XAI_BASE_URL ?? \\\"https://api.x.ai/v1\\\"}/responses`, { method: \\\"POST\\\", headers: { Authorization: `Bearer ${apiKey}`, \\\"content-type\\\": \\\"application/json\\\" }, body: JSON.stringify(body), signal });\\n  const data: any = await r.json(); if (!r.ok) throw new Error(`xAI HTTP ${r.status}: ${data?.error?.message ?? \\\"request failed\\\"}`);\\n  const text = (data.output ?? []).flatMap((o: any) => o.content ?? []).filter((c: any) => c.type === \\\"output_text\\\").map((c: any) => c.text).join(\\\"\\\\n\\\\n\\\");\\n  return { tool, query: p.query, answer: text, citations: data.citations ?? [], requestHash: createHash(\\\"sha256\\\").update(JSON.stringify(body)).digest(\\\"hex\\\") };\\n}\\nexport default function swarmSearchExtension(pi: any) {\\n  pi.registerTool({ name: \\\"xai_web_search\\\", label: \\\"xAI Web Search\\\", description: \\\"Search the live web through xAI with citations. Requires XAI_API_KEY.\\\", parameters: webSchema, async execute(_id: string, p: any, signal: AbortSignal) { try { return { content: [{ type: \\\"text\\\", text: JSON.stringify(await search(\\\"web_search\\\", p, signal)) }], details: {} }; } catch (e) { return { content: [{ type: \\\"text\\\", text: e instanceof Error ? e.message : String(e) }], isError: true, details: {} }; } } });\\n  pi.registerTool({ name: \\\"x_search\\\", label: \\\"X Search\\\", description: \\\"Search X posts and profiles through xAI. Requires XAI_API_KEY.\\\", parameters: xSchema, async execute(_id: string, p: any, signal: AbortSignal) { try { return { content: [{ type: \\\"text\\\", text: JSON.stringify(await search(\\\"x_search\\\", p, signal)) }], details: {} }; } catch (e) { return { content: [{ type: \\\"text\\\", text: e instanceof Error ? e.message : String(e) }], isError: true, details: {} }; } } });\\n}\\n\"\n  ],\n  \"toolCalls\": [\n    {\n      \"name\": \"workspace.read\"\n    },\n    {\n      \"name\": \"workspace.read\"\n    },\n    {\n      \"name\": \"workspace.read\"\n    },\n    {\n      \"name\": \"workspace.read\"\n    },\n    {\n      \"name\": \"workspace.read\"\n    }\n  ]\n}"}],"details":{"ok":true,"value":["import { registerAutoSkills, type Config } from \"../../autogenskills/src/index.ts\";\nimport { fileURLToPath } from \"node:url\";\nimport { join, resolve } from \"node:path\";\nimport { readFileSync, writeFileSync, mkdirSync } from \"node:fs\";\nimport \"../hook-state.ts\";\n\n/** Pi adapter for Swarm's stateful autogenerated-skills lifecycle. */\nexport interface AutoSkillsExtensionOptions extends Config {}\n\nconst settingsFile = (cwd: string) => join(resolve(cwd), \".pi\", \"swarm-settings.json\");\nfunction autogenMode(cwd: string): Config[\"mode\"] {\n  const env = process.env.SWARM_AUTOGEN_MODE as Config[\"mode\"] | undefined;\n  if (env && [\"never\", \"manual\", \"auto\"].includes(env)) return env;\n  try {\n    const value = JSON.parse(readFileSync(settingsFile(cwd), \"utf8\")).autogen;\n    if (value === false || value === \"off\" || value === \"never\") return \"never\";\n    if (value === \"manual\") return \"manual\";\n    if (value === true || value === \"on\" || value === \"auto\") return \"auto\";\n  } catch { /* absent settings use the Swarm default */ }\n  return \"auto\";\n}\nfunction saveAutogenMode(cwd: string, mode: Config[\"mode\"]): void {\n  const path = settingsFile(cwd); mkdirSync(join(resolve(cwd), \".pi\"), { recursive: true });\n  let settings: any = {}; try { settings = JSON.parse(readFileSync(path, \"utf8\")); } catch {}\n  settings.autogen = mode === \"never\" ? false : mode;\n  writeFileSync(path, `${JSON.stringify(settings, null, 2)}\\n`, \"utf8\");\n}\n\nexport function registerAutoSkillsExtension(pi: any, options: AutoSkillsExtensionOptions = {}) {\n  const child = process.env.SWARM_CURATOR_CHILD === \"1\";\n  const extensionPath = fileURLToPath(import.meta.url);\n  const configuredDir = options.dir ?? process.env.SWARM_AUTOGEN_DIR;\n  const dir = configuredDir?.trim() || join(process.env.HOME ?? process.cwd(), \".swarm\", \"skills\", \"autogen\");\n  const curatorRunner = options.curatorRunner ?? (!child && typeof pi.exec === \"function\"\n    ? async (request: Parameters<NonNullable<Config[\"curatorRunner\"]>>[0]) => {\n      const result = await pi.exec(\"env\", [\n        `SWARM_AUTOGEN_MODE=manual`,\n        `SWARM_AUTOGEN_DIR=${dir}`,\n        `SWARM_AUTOGEN_PREVIEW=${request.preview ? \"1\" : \"0\"}`,\n        \"SWARM_AUTOGEN_REQUIRE_VIEW=1\",\n        \"SWARM_AUTOGEN_ACCOUNTING_EXEMPT=1\",\n        \"SWARM_CURATOR_CHILD=1\",\n        \"pi\",\n        \"--no-session\",\n        \"--no-extensions\",\n        \"--extension\", extensionPath,\n        \"--no-skills\",\n        \"--no-context-files\",\n        \"--no-prompt-templates\",\n        \"--tools\", \"SkillManage\",\n        \"--mode\", \"text\",\n        \"-p\", request.prompt,\n      ], { cwd: process.cwd(), timeout: request.timeoutMs });\n      if (result.code !== 0 || result.killed) {\n        throw new Error(`curator child failed (${result.killed ? \"timeout\" : `exit ${result.code}`}): ${result.stderr.trim()}`);\n      }\n      return { output: result.stdout.trim() };\n    }\n    : undefined);\n  return registerAutoSkills(pi, {\n    ...options,\n    budgetWidget: undefined,\n    dir,\n    previewOnly: options.previewOnly ?? process.env.SWARM_AUTOGEN_PREVIEW === \"1\",\n    requireReadBeforeWrite: options.requireReadBeforeWrite ?? process.env.SWARM_AUTOGEN_REQUIRE_VIEW === \"1\",\n    accountingExempt: options.accountingExempt ?? process.env.SWARM_AUTOGEN_ACCOUNTING_EXEMPT === \"1\",\n    curatorRunner,\n  });\n}\n\nexport default function autogenskillsExtension(pi: any) {\n  // Swarm autogen is enabled by default, but remains isolated from Pi's\n  // native skill ecosystem. Persisted project settings or the environment can\n  // disable it without exposing generated skills to Pi discovery.\n  const cwd = resolve(pi.getCwd?.() ?? process.cwd());\n  const mode = autogenMode(cwd);\n  pi.registerCommand?.(\"swarm-autogen\", { description: \"Show or change Swarm autogenerated-skills mode (on, off, manual, status)\", handler: async (args: string, ctx: any) => {\n    const value = args.trim().toLowerCase();\n    if (value === \"status\" || !value) { ctx.ui?.notify?.(`Swarm autogen: ${mode} (default: auto; applies on next session)`, \"info\"); return; }\n    const next = value === \"on\" ? \"auto\" : value === \"off\" ? \"never\" : value;\n    if (![\"auto\", \"manual\", \"never\"].includes(next)) { ctx.ui?.notify?.(\"Usage: /swarm-autogen on|off|manual|status\", \"warning\"); return; }\n    saveAutogenMode(cwd, next as Config[\"mode\"]);\n    ctx.ui?.notify?.(`Swarm autogen set to ${next}; restart or reload the session to apply.`, \"info\");\n  }});\n  if (mode === \"never\") return;\n  registerAutoSkillsExtension(pi, { mode, dir: process.env.SWARM_AUTOGEN_DIR || undefined });\n  // Prompt composition is owned by swarm-prompt.ts. Autogen contributes\n  // lifecycle nudges only when enabled by settings or environment.\n}\n","import { getSwarmSkillRegistry, type SkillLoaderOptions } from \"../lib/swarm-skill-registry.ts\";\n\nexport interface SwarmSkillsOptions extends SkillLoaderOptions { watch?: boolean; }\n\nexport function registerSwarmSkills(pi: any, options: SwarmSkillsOptions = {}) {\n  // Normal operation includes installed, project, user, and autogenerated skills.\n  // Closed mode remains explicit and only admits the configured CLI paths.\n  const registry = getSwarmSkillRegistry(pi, { cwd: options.cwd ?? process.cwd(), ...options, closed: options.closed ?? (process.env.SWARM_SKILLS_CLOSED === \"1\") });\n  let current = registry.refresh();\n  const bridged: any[] = [];\n  const originalRegister = pi.registerTool?.bind(pi);\n  pi.registerTool = (tool: unknown) => { bridged.push(tool); originalRegister?.(tool); };\n  (pi as any).codemodeTools = [...((pi as any).codemodeTools ?? []), ...bridged];\n  const refresh = () => { current = registry.refresh(); };\n  if (options.watch) registry.loader.watch(refresh);\n  pi.on?.(\"session_start\", refresh);\n  // Prompt composition is owned by swarm-prompt.ts. This extension owns only\n  // discovery, invocation, and the inspection command; registering another\n  // systemPrompt writer here can overwrite the Forge assembly.\n  pi.registerCommand?.(\"skill\", { description: \"List discovered Swarm skills and their sources\", handler: async (_args: string, ctx: any) => {\n    current = registry.refresh();\n    const text = current.skills.map(s => `${s.name} [${s.source}] — ${s.description}`).join(\"\\n\") || \"No skills discovered\";\n    ctx.ui?.notify?.(text, \"info\");\n  }});\n  pi.registerCommand?.(\"swarm-skills\", { description: \"List discovered Swarm skills\", handler: async (args: string, ctx: any) => {\n    current = registry.refresh();\n    const requested = args.trim();\n    const skill = requested ? registry.find(requested) : undefined;\n    ctx.ui?.notify?.(skill ? `${skill.name} [${skill.source}]\\n${skill.description}` : current.skills.map(s => `${s.name} [${s.source}] — ${s.description}`).join(\"\\n\") || \"No skills discovered\", \"info\");\n  }});\n  // The autogenskills extension owns the canonical model-facing `Skill` tool\n  // and invokes its stateful manager. This extension must not register a second\n  // tool with the same name; it only supplies the shared discovery registry and\n  // the user-facing discovery commands.\n  return { loader: registry.loader, registry, getResult: () => current };\n}\n\nexport default function swarmSkillsExtension(pi: any) { return registerSwarmSkills(pi); }\n","import { SkillLoader, generateAvailableSkillsXML, type LoadedSkill, type SkillLoaderOptions, type SkillLoadResult } from \"../../skills/src/index.ts\";\n\n/** One registry shared by the model-facing Skill tool, prompt catalog, and /skill command. */\nexport class SwarmSkillRegistry {\n  readonly loader: SkillLoader;\n  private result: SkillLoadResult;\n  constructor(options: SkillLoaderOptions = {}) { this.loader = new SkillLoader({ ...options, closed: options.closed ?? false }); this.result = this.loader.load(); }\n  refresh(): SkillLoadResult { this.result = this.loader.load(); return this.result; }\n  list(): LoadedSkill[] { return this.result.skills; }\n  find(name: string): LoadedSkill | undefined { return this.result.skills.find(s => s.name === name); }\n  catalog(): string { return generateAvailableSkillsXML(this.result.skills.filter(s => !s.disableModelInvocation)); }\n}\n\nexport type { LoadedSkill, SkillLoaderOptions, SkillLoadResult };\n\nconst registries = new WeakMap<object, SwarmSkillRegistry>();\nexport function getSwarmSkillRegistry(pi: object, options: SkillLoaderOptions = {}): SwarmSkillRegistry {\n  let registry = registries.get(pi);\n  if (!registry) { registry = new SwarmSkillRegistry(options); registries.set(pi, registry); }\n  return registry;\n}\n","import { createHash } from \"node:crypto\";\nimport { existsSync, readFileSync, readdirSync, statSync } from \"node:fs\";\nimport { extname, isAbsolute, join, relative, resolve } from \"node:path\";\nimport { registerHook } from \"../hook-state.ts\";\nimport { getSwarmSkillRegistry } from \"../lib/swarm-skill-registry.ts\";\n\nimport {\n  UPSTREAM_SOURCE,\n  forgeSwarmSystemPrompt,\n  swarmForgeSystemPrompt,\n} from \"../../swarm-prompt/src/index.ts\";\nimport { resolveActiveSystemPrompt } from \"./system-prompts.ts\";\n\nexport { UPSTREAM_SOURCE, forgeSwarmSystemPrompt, swarmForgeSystemPrompt };\n\nconst forgeMarker = \"<!-- pi-swarm:forge-prompt:v1 -->\";\n\nexport interface PromptExtensionEvent {\n  systemPrompt: string;\n  systemPromptOptions?: { cwd?: string };\n  /** Optional Forge prompt controls supplied by the host/bridge. */\n  swarmPrompt?: PromptAssemblyOptions;\n}\nexport interface PromptExtensionContext { cwd?: string; }\nexport interface PromptProvenance { section: string; origin: string; ref: string; hash: string; bytes: number; }\nexport interface WorkspaceContext { cwd: string; os: string; shell: string; home: string; extensions: string[]; }\nexport interface ContextFile { path: string; content: string; }\nexport interface PromptAssemblyOptions {\n  cwd?: string;\n  userPrompt?: string;\n  tools?: Array<string | { name: string; guidance: string }>;\n  toolGuidance?: Record<string, string>;\n  skills?: Array<{ name: string; instructions: string; version?: string }>;\n  contextFiles?: string[];\n  contextFileNames?: string[];\n  restrictions?: string[];\n  /** Explicitly opt out of convention-file discovery. */\n  discoverContextFiles?: boolean;\n  maxContextFileBytes?: number;\n}\nexport interface PromptAssembly {\n  prompt: string;\n  hash: string;\n  workspace: WorkspaceContext;\n  provenance: PromptProvenance[];\n  contextFiles: string[];\n}\n\nconst hash = (value: string) => `sha256:${createHash(\"sha256\").update(value).digest(\"hex\")}`;\nconst clean = (value: string) => value.replace(/\\r\\n/g, \"\\n\").trim();\nconst contained = (root: string, candidate: string) => {\n  const r = relative(root, candidate);\n  return r === \"\" || (r !== \"..\" && !r.startsWith(`..${\"/\"}`) && !isAbsolute(r));\n};\nconst safeRef = (root: string, path: string) => {\n  const absolute = resolve(root, path);\n  return contained(root, absolute) ? absolute : undefined;\n};\n\nexport function resolveWorkspace(cwd = process.cwd()): WorkspaceContext {\n  const root = resolve(cwd);\n  const exte